// Revenue conversion hook: records paid event on checkout success
const fs = require('fs');
const path = require('path');

const REVENUE_LOG = path.join(__dirname, '..', 'data', 'revenue_events.log');

function recordPaidEvent(amount, currency, userId) {
  const event = {
    type: 'paid',
    amount,
    currency: currency || 'USD',
    userId: userId || 'anonymous',
    timestamp: new Date().toISOString()
  };
  fs.appendFileSync(REVENUE_LOG, JSON.stringify(event) + '\n');
  console.log('[RevenueConversion] Recorded paid event:', event);
}

// Hook to be called on checkout success
function onCheckoutSuccess(req, res, next) {
  const { amount, currency, userId } = req.body || {};
  if (amount && amount > 0) {
    recordPaidEvent(amount, currency, userId);
  }
  if (next) next();
}

module.exports = { recordPaidEvent, onCheckoutSuccess };
